package you.v50to.eatwhat.control;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import tools.jackson.databind.json.JsonMapper;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

/** Actual private files/cross-process lock; remote/authority responses simulated. */
class ControlDeploymentRecoveryTest {
    @TempDir Path root;ControlProperties settings;ControlAudit audit;ControlServerStore files;DeploymentExecutor deployment;ControlDeploymentRecovery recovery;Fake transport;
    final UUID job=UUID.randomUUID(),instance=UUID.randomUUID();final String old="a".repeat(64),candidate="b".repeat(64);Map<String,Object> journal;
    final JsonMapper json=JsonMapper.builder().build();
    @BeforeEach void setup(){settings=new ControlProperties();settings.setEnvironmentKind("isolated-acceptance");settings.getDeployment().setTargetSource(ControlProperties.Deployment.TargetSource.REGISTERED_SERVERS);settings.getDeployment().setEnabled(true);settings.getDeployment().setTimeoutSeconds(30);audit=new ControlAudit(root.resolve("state"));files=new ControlServerStore(audit);deployment=new DeploymentExecutor(settings,audit);transport=new Fake();deployment.registeredTransport(transport);recovery=new ControlDeploymentRecovery(settings,audit,files,deployment);
        var target=new ControlProperties.DeploymentTarget();target.setServerId(UUID.randomUUID());target.setServerRevision(1);target.setSiteId("campus");target.setInstanceId(instance);target.setCurrentSha256(old);target.setDeploymentManifestHash("c".repeat(64));target.setRemoteConfigurationProof("d".repeat(64));target.setMembershipEpoch(1);target.setEncryptedConnection("synthetic-private-frozen-connection");target.setEncryptedAuthorityToken("synthetic-private-capability");
        journal=new LinkedHashMap<>(Map.of("id",job.toString(),"releaseId","candidate","artifactSha256",candidate,"state","OUTCOME_UNKNOWN","_registered",true,"_remoteDispatchAllowed",true,"_manifestHash","c".repeat(64),"_targets",List.of(target),"targets",new ArrayList<>(List.of(new LinkedHashMap<>(Map.of("site","campus","siteId","campus","instanceId",instance.toString(),"fromSha256",old,"state","OUTCOME_UNKNOWN"))))));saveJob();
    }
    @AfterEach void stop(){transport.release.countDown();recovery.close();deployment.close();}
    void saveJob(){files.saveJson(audit.directory().resolve("deployment-"+job+".json"),journal);}
    Path path(UUID id){return audit.directory().resolve("deployment-recovery-plan-"+id+".json");}
    Map<String,Object> done(UUID id)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<end){var result=recovery.get(id);if(!Set.of("QUEUED","RUNNING").contains(result.get("state")))return result;Thread.sleep(10);}throw new AssertionError("Recovery fixture did not finish");}
    void parentDone()throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<end){if("FAILED".equals(deployment.get(job).get("state")))return;Thread.sleep(10);}fail("Parent did not reconcile");}
    final class Fake implements DeploymentExecutor.RegisteredTransport {
        final AtomicInteger effects=new AtomicInteger(),reads=new AtomicInteger(),previews=new AtomicInteger();final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);boolean lostAck,block,revoked,badReply;boolean finalized;String recoveryResult="SUCCEEDED";
        public boolean available(){return true;}public ControlProperties.DeploymentTarget resolve(DeploymentExecutor.Target ignored){throw new AssertionError("Never resolve current registry for recovery");}
        public void requireRecovery(UUID id,String manifest,boolean applying){if(revoked)throw new ControlFailure(409,"DEPLOYMENT_FENCE_NOT_ACTIVE");assertEquals(job,id);assertEquals("c".repeat(64),manifest);}
        public Map<String,Object> recovery(String action,UUID id,ControlProperties.DeploymentTarget target,String sha,UUID request,String proof)throws Exception{
            assertEquals("synthetic-private-frozen-connection",target.getEncryptedConnection());assertEquals(job,id);
            if(action.equals("recovery-prepare")){previews.incrementAndGet();return Map.of("state","RECOVERY_PREPARED","recoveryRequestId",request.toString(),"recoveryProof","e".repeat(64),"restoreSha256",old,"currentSha256",candidate,"databaseIdentityVerified",true);}
            if(action.equals("recover")){effects.incrementAndGet();entered.countDown();if(block)assertTrue(release.await(5,TimeUnit.SECONDS));if(lostAck)throw new java.io.IOException("Synthetic lost acknowledgement");}else{assertEquals("recovery-status",action);reads.incrementAndGet();}
            return Map.of("state",badReply?"SUCCEEDED":recoveryResult.equals("SUCCEEDED")?"ROLLED_BACK":"OUTCOME_UNKNOWN","recovery",Map.of("id",request.toString(),"state",recoveryResult,"stage","COMPLETE","code","RELEASE_MANUAL_ROLLBACK_RUNTIME_VERIFIED"));
        }
        public Map<String,Object> call(String action,UUID id,ControlProperties.DeploymentTarget t,Path artifact,String sha){assertEquals("status",action);return Map.of("id",id.toString(),"siteId",t.getSiteId(),"instanceId",t.getInstanceId().toString(),"artifactSha256",sha,"state","ROLLED_BACK");}
        public void complete(UUID id,String manifest,Map<String,Object> job){finalized=true;}public boolean finalized(UUID id,String manifest,Map<String,Object> job){return finalized;}
    }
    @Test void previewIsReadonlyAndPublicViewsNeverExposeFrozenCredentialsOrProof(){UUID id=UUID.randomUUID();var plan=recovery.create("admin",job,id,"campus");assertEquals("PREVIEW_ONLY",plan.get("state"));assertEquals(0,transport.effects.get());assertFalse(plan.toString().contains("synthetic-private"));assertFalse(plan.containsKey("_remoteProof"));assertEquals(1,transport.previews.get());assertEquals(json.writeValueAsString(plan),json.writeValueAsString(recovery.create("admin",job,id,"campus")));assertEquals(1,transport.previews.get());assertFalse(deployment.get(job).containsKey("recoveryAttempts"));}
    @Test void explicitConfirmationAndFreshPreviewAreRequiredBeforeAnyRemoteEffect(){UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");assertEquals("DEPLOYMENT_RECOVERY_CONFIRMATION_REQUIRED",assertThrows(ControlFailure.class,()->recovery.execute("admin",id,candidate)).code);var plan=files.readJson(path(id));plan.put("expiresAt",Instant.now().minusSeconds(1).toString());files.saveJson(path(id),plan);assertEquals("DEPLOYMENT_RECOVERY_PLAN_EXPIRED",assertThrows(ControlFailure.class,()->recovery.execute("admin",id,old)).code);assertEquals(0,transport.effects.get());}
    @Test void successfulManualRecoveryIsOnceAndOriginalTaskRemainsTheHistoryAnchor()throws Exception{UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");recovery.execute("admin",id,old);assertEquals("SUCCEEDED",done(id).get("state"));parentDone();assertEquals("SUCCEEDED",recovery.execute("admin",id,old).get("state"));assertEquals(1,transport.effects.get());var parent=deployment.get(job);assertEquals("FAILED",parent.get("state"));assertTrue(parent.toString().contains(id.toString()));assertFalse(parent.toString().contains("synthetic-private"));assertTrue(transport.finalized);}
    @Test void lostAcknowledgementOrRestartOnlyReadsAndNeverResends()throws Exception{transport.lostAck=true;UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");recovery.execute("admin",id,old);assertEquals("OUTCOME_UNKNOWN",done(id).get("state"));recovery.close();recovery=new ControlDeploymentRecovery(settings,audit,files,deployment);assertEquals("OUTCOME_UNKNOWN",recovery.execute("admin",id,old).get("state"));assertEquals(1,transport.effects.get());assertEquals("SUCCEEDED",recovery.reconcile("admin",id).get("state"));assertEquals(1,transport.effects.get());assertEquals(1,transport.reads.get());parentDone();}
    @Test void changedOriginalBindingOrControllerCodeRejectsThePreview(){UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");var plan=files.readJson(path(id));plan.put("_controllerSha","changed-code");files.saveJson(path(id),plan);assertEquals("DEPLOYMENT_RECOVERY_PLAN_RECREATE_REQUIRED",assertThrows(ControlFailure.class,()->recovery.execute("admin",id,old)).code);plan.put("_controllerSha","ISOLATED_CLASSES");files.saveJson(path(id),plan);var target=(ControlProperties.DeploymentTarget)((List<?>)journal.get("_targets")).getFirst();target.setHost("different.invalid");saveJob();assertEquals("DEPLOYMENT_RECOVERY_PLAN_RECREATE_REQUIRED",assertThrows(ControlFailure.class,()->recovery.execute("admin",id,old)).code);assertEquals(0,transport.effects.get());}
    @SuppressWarnings("unchecked") @Test void knownSuccessfulTargetOrRevokedAuthorityCannotBeRestored(){((List<Map<String,Object>>)journal.get("targets")).getFirst().put("state","SUCCEEDED");saveJob();assertEquals("DEPLOYMENT_RECOVERY_NOT_ELIGIBLE",assertThrows(ControlFailure.class,()->recovery.create("admin",job,UUID.randomUUID(),"campus")).code);((List<Map<String,Object>>)journal.get("targets")).getFirst().put("state","OUTCOME_UNKNOWN");saveJob();transport.revoked=true;assertEquals("DEPLOYMENT_FENCE_NOT_ACTIVE",assertThrows(ControlFailure.class,()->recovery.create("admin",job,UUID.randomUUID(),"campus")).code);assertEquals(0,transport.effects.get());}
    @Test void recoveryHoldsTheExistingGlobalDeploymentLockAndDuplicateClickDoesNotDispatchAgain()throws Exception{transport.block=true;UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");recovery.execute("admin",id,old);assertTrue(transport.entered.await(3,TimeUnit.SECONDS));assertEquals("RUNNING",recovery.execute("admin",id,old).get("state"));assertEquals("DEPLOYMENT_RUNNING",deployment.whenIdle(()->fail("New operation must remain blocked")));assertEquals("DEPLOYMENT_ALREADY_ACTIVE",assertThrows(ControlFailure.class,()->recovery.create("admin",job,UUID.randomUUID(),"campus")).code);assertEquals(1,transport.effects.get());transport.release.countDown();assertEquals("SUCCEEDED",done(id).get("state"));}
    @Test void childSuccessWithoutVerifiedParentRollbackStaysUnknown()throws Exception{transport.badReply=true;UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");recovery.execute("admin",id,old);assertEquals("OUTCOME_UNKNOWN",done(id).get("state"));assertFalse(transport.finalized);assertEquals("OUTCOME_UNKNOWN",deployment.get(job).get("state"));}
    @Test void stoppingNewAdmissionOrChangingTargetSourceDoesNotStrandAnAlreadyAdmittedFrozenJob()throws Exception{UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");settings.getDeployment().setEnabled(false);settings.getDeployment().setTargetSource(ControlProperties.Deployment.TargetSource.STATIC);assertTrue(deployment.recoverySupported());recovery.execute("admin",id,old);assertEquals("SUCCEEDED",done(id).get("state"));assertEquals(1,transport.effects.get());}
    @Test void anotherControllerCannotResendAUuidFromAStalePreviewReadAfterTheFirstAttemptFailed()throws Exception{
        transport.recoveryResult="FAILED";UUID id=UUID.randomUUID();recovery.create("admin",job,id,"campus");var firstRead=new CountDownLatch(1);var resume=new CountDownLatch(1);var calls=new AtomicInteger();
        java.util.function.Function<Path,Map<String,Object>> delayed=p->{var snapshot=files.readJson(p);if(p.equals(path(id))&&calls.getAndIncrement()==0){firstRead.countDown();try{assertTrue(resume.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}}return snapshot;};
        try(var second=new ControlDeploymentRecovery(settings,audit,files,deployment,delayed);var threads=Executors.newVirtualThreadPerTaskExecutor()){
            var waiting=threads.submit(()->second.execute("other-admin",id,old));assertTrue(firstRead.await(3,TimeUnit.SECONDS));recovery.execute("admin",id,old);assertEquals("FAILED",done(id).get("state"));assertEquals(1,transport.effects.get());long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);String guard;do{guard=deployment.whenIdle(()->fail("Original unknown task must stay blocked"));if(!"DEPLOYMENT_RUNNING".equals(guard))break;Thread.sleep(10);}while(System.nanoTime()<end);assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",guard);resume.countDown();assertEquals("FAILED",waiting.get(5,TimeUnit.SECONDS).get("state"));assertEquals(1,transport.effects.get());
        }finally{resume.countDown();}
    }
}
